#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        pref[i + 1] = pref[i] + a[i];
    }

    long long max_sum = a[0];
    long long curr = 0;
    for (int i = 0; i < n; i++) {
        curr = max(a[i], curr + a[i]);
        max_sum = max(max_sum, curr);
    }

    cout << max_sum << "\n";
    return 0;
}

