        int left = 0;
        long currentSum = 0;
        int maxLen = 0;

        for (int right = 0; right < n; right++) {
            currentSum += a[right];
            while (left <= right && currentSum > target) {
                currentSum -= a[left];
                left++;
            }
            if (currentSum <= target) {
                maxLen = Math.max(maxLen, right - left + 1);
            }
        }
        System.out.println(maxLen);
    }
}

